function doLogin(){
  const email=(document.getElementById('login-email')?.value||'').trim().toLowerCase();
  const pass=(document.getElementById('login-password')?.value||'').trim();
  const errEl=document.getElementById('login-error');
  const match=DEMO_ACCOUNTS.find(a=>a.email===email&&a.password===pass);
  if(match){
    if(errEl)errEl.style.display='none';
    showPage('therapist-dashboard');
  } else {
    if(errEl)errEl.style.display='block';
    document.getElementById('login-password').value='';
  }
}

// ── PAGES ──────────────────────────────────────────────────────────────────
const ALL_PAGES=['home','dir','profile','therapist-login','therapist-signup','therapist-dashboard'];
function showPage(name,opts={}){
  ALL_PAGES.forEach(p=>{
    const el=document.getElementById(p+'-page');
    if(el){el.style.display='none';el.classList.remove('visible');}
  });
  currentPage=name;
  const target=document.getElementById(name+'-page');
  if(!target)return;
  target.style.display='block';
  requestAnimationFrame(()=>{target.classList.add('visible');});
  window.scrollTo(0,0);
  if(name==='dir'){initDir();}
  if(name==='profile'&&opts.id){renderProfile(opts.id);}
  if(name==='therapist-dashboard'){initDashboard();}
}

