// ── STATS ──────────────────────────────────────────────────────────────────
function initStats(){
  const els=document.querySelectorAll('.stat-num');
  if(!els.length)return;
  const obs=new IntersectionObserver(entries=>{
    entries.forEach(e=>{
      if(e.isIntersecting){
        animateStat(e.target);
        obs.unobserve(e.target);
      }
    });
  },{threshold:.5});
  els.forEach(el=>obs.observe(el));
}
function animateStat(el){
  const target=+el.dataset.count;
  const fmt=el.dataset.format||'';
  const suffix=el.dataset.suffix||'';
  const dur=1600;
  const start=performance.now();
  function frame(now){
    const p=Math.min((now-start)/dur,1);
    const ease=1-Math.pow(1-p,3);
    const val=target*ease;
    if(fmt==='K'){el.textContent=val>=950?'1K+':(Math.round(val/100)/10).toFixed(0)+'K+';}
    else if(fmt==='decimal'){el.textContent=(val/10).toFixed(1)+suffix;}
    else{el.textContent=Math.round(val)+suffix;}
    if(p<1)requestAnimationFrame(frame);
    else{
      if(fmt==='K'){el.textContent=target>=1000?(target/1000)+'K+':target+'K+';}
      else if(fmt==='decimal'){el.textContent=(target/10).toFixed(1)+suffix;}
      else{el.textContent=target+suffix;}
    }
  }
  requestAnimationFrame(frame);
}

