function renderSpecGrid(){
  const g=document.getElementById('spec-grid');
  if(!g)return;
  g.innerHTML=SPECIALTIES_DISPLAY.map(s=>`
    <div class="spec-card" onclick="filterBySpec('${s.title}')">
      <div class="spec-icon">${s.icon}</div>
      <div class="spec-title">${s.title}</div>
      <div class="spec-sub">${s.sub}</div>
    </div>`).join('');
}
function filterBySpec(title){
  showPage('dir');
  setTimeout(()=>{
    const sel=document.getElementById('f-specialty');
    if(sel){
      const opt=Array.from(sel.options).find(o=>o.value.toLowerCase().includes(title.split(' ')[0].toLowerCase()));
      if(opt){sel.value=opt.value;applyFilters();}
    }
  },100);
}

// ── MEADOW CHAT ───────────────────────────────────────────────────────────
function initMeadow(){
  meadowStep=0;meadowSelections={};
  const inputRow=document.getElementById('meadow-input-row');
  if(inputRow)inputRow.style.display='none';
  renderMeadowStep();
}
function renderMeadowStep(){
  const step=MEADOW_FLOW[meadowStep];
  if(!step)return;
  const msgs=document.getElementById('chat-messages');
  const optWrap=document.getElementById('chat-options-wrap');
  const inputRow=document.getElementById('meadow-input-row');
  const textInput=document.getElementById('meadow-text-input');
  if(!msgs||!optWrap)return;
  if(meadowStep===0){msgs.innerHTML='';optWrap.innerHTML='';}

  // Show typing indicator
  const typing=document.createElement('div');
  typing.className='chat-msg';
  typing.innerHTML=`<div class="chat-msg-avatar"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="white" stroke-width="2.5"><path d="M12 2C8 2 5 5 5 9c0 4 3 8 7 11 4-3 7-7 7-11 0-4-3-7-7-7z"/></svg></div><div class="typing-dots"><span></span><span></span><span></span></div>`;
  msgs.appendChild(typing);
  msgs.scrollTop=msgs.scrollHeight;

  setTimeout(()=>{
    typing.remove();
    const msgEl=document.createElement('div');
    msgEl.className='chat-msg';
    msgEl.innerHTML=`<div class="chat-msg-avatar"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="white" stroke-width="2.5"><path d="M12 2C8 2 5 5 5 9c0 4 3 8 7 11 4-3 7-7 7-11 0-4-3-7-7-7z"/></svg></div><div class="chat-msg-bubble">${step.msg}</div>`;
    msgs.appendChild(msgEl);
    msgs.scrollTop=msgs.scrollHeight;

    if(step.type==='options'){
      optWrap.innerHTML=`<div class="chat-options">${step.options.map(o=>`<button class="chat-option" onclick="selectMeadowOption('${o.replace(/'/g,"\\'")}',this)">${o}</button>`).join('')}</div>`;
      // Show the text input so user can type freely instead of/in addition to chips
      if(inputRow){inputRow.style.display='flex';}
      if(textInput){textInput.disabled=false;setTimeout(()=>textInput.focus(),50);}
    } else if(step.type==='action'){
      optWrap.innerHTML='';
      if(inputRow)inputRow.style.display='none';
      setTimeout(()=>{showPage('dir');},1200);
    }
  },800);
}

function detectMeadowValue(stepId,text){
  const t=text.toLowerCase();
  if(stepId==='welcome'){
    if(/anxi|worry|stress|panic|nerv|overwhelm/.test(t))return'Anxiety or worry';
    if(/depress|sad|low mood|hopeless|unmotiv/.test(t))return'Depression or low mood';
    if(/relation|partner|couple|marr|divorce|family|parent/.test(t))return'Relationship challenges';
    if(/trauma|ptsd|abuse|past|childhood|assault/.test(t))return'Trauma or past experiences';
    if(/transit|change|job|career|loss|grief|moving|major life/.test(t))return'Life transition or change';
    return"I'm not sure yet";
  }
  if(stepId==='province'){
    if(/b\.?c\.?|british columbia|vancouver|victoria|kelowna/.test(t))return'British Columbia';
    if(/ontario|toronto|ottawa|hamilton|brampton|mississauga/.test(t))return'Ontario';
    if(/albert|calgary|edmonton|red deer/.test(t))return'Alberta';
    if(/qu[eé]bec|montreal|laval|gatineau/.test(t))return'Québec';
    if(/nova|halifax|cape breton/.test(t))return'Nova Scotia';
    return'Other province';
  }
  if(stepId==='insurance'){
    if(/blue cross/.test(t))return'Blue Cross';
    if(/sun life/.test(t))return'Sun Life Financial';
    if(/manulife/.test(t))return'Manulife';
    if(/green shield/.test(t))return'Green Shield Canada';
    if(/canada life/.test(t))return'Canada Life';
    if(/no |none|skip|self.?pay|out.?of.?pocket|cash/.test(t))return"Skip — I'll pay out of pocket";
    return text;
  }
  return text;
}

function handleMeadowText(){
  const textInput=document.getElementById('meadow-text-input');
  if(!textInput)return;
  const raw=textInput.value.trim();
  if(!raw)return;
  textInput.value='';

  const step=MEADOW_FLOW[meadowStep];
  if(!step||step.type!=='options')return;

  // Show user message bubble
  const msgs=document.getElementById('chat-messages');
  const userMsg=document.createElement('div');
  userMsg.style.cssText='text-align:right;margin-top:6px';
  userMsg.innerHTML=`<span style="background:var(--primary);color:#fff;border-radius:16px 4px 16px 16px;padding:8px 14px;font-size:14px;display:inline-block;max-width:85%">${raw}</span>`;
  msgs.appendChild(userMsg);
  msgs.scrollTop=msgs.scrollHeight;

  // Disable chips + input while processing
  document.querySelectorAll('#chat-options-wrap .chat-option').forEach(b=>b.disabled=true);
  textInput.disabled=true;

  const detected=detectMeadowValue(step.id,raw);
  meadowSelections[step.id]=detected;

  meadowStep++;
  if(meadowStep<MEADOW_FLOW.length){
    document.getElementById('chat-options-wrap').innerHTML='';
    textInput.disabled=false;
    setTimeout(renderMeadowStep,400);
  }
}

function selectMeadowOption(val,btn){
  document.querySelectorAll('#chat-options-wrap .chat-option').forEach(b=>b.disabled=true);
  const textInput=document.getElementById('meadow-text-input');
  if(textInput)textInput.disabled=true;
  btn.classList.add('selected');
  meadowSelections[MEADOW_FLOW[meadowStep].id]=val;

  const msgs=document.getElementById('chat-messages');
  const userMsg=document.createElement('div');
  userMsg.style.cssText='text-align:right;margin-top:6px';
  userMsg.innerHTML=`<span style="background:var(--primary);color:#fff;border-radius:16px 4px 16px 16px;padding:8px 14px;font-size:14px;display:inline-block;max-width:85%">${val}</span>`;
  msgs.appendChild(userMsg);
  msgs.scrollTop=msgs.scrollHeight;

  meadowStep++;
  if(meadowStep<MEADOW_FLOW.length){
    document.getElementById('chat-options-wrap').innerHTML='';
    if(textInput)textInput.disabled=false;
    setTimeout(renderMeadowStep,400);
  }
}
function startMeadowFlow(){
  showPage('home');
  setTimeout(()=>{initMeadow();},100);
  window.scrollTo(0,0);
}

// ── DIRECTORY ─────────────────────────────────────────────────────────────
function initDir(){
  const provSel=document.getElementById('f-province');
  const specSel=document.getElementById('f-specialty');
  const issueSel=document.getElementById('f-issue');
  const insSel=document.getElementById('f-insurance');
  const ageSel=document.getElementById('f-age');
  const langSel=document.getElementById('f-lang');
  if(provSel&&provSel.children.length<=1){
    FILTER_OPTIONS.provinces.forEach(p=>{const o=document.createElement('option');o.value=p;o.textContent=p;provSel.appendChild(o);});
  }
  if(specSel&&specSel.children.length<=1){
    FILTER_OPTIONS.specialties.forEach(s=>{const o=document.createElement('option');o.value=s;o.textContent=s;specSel.appendChild(o);});
  }
  if(issueSel&&issueSel.children.length<=1){
    FILTER_OPTIONS.issues.forEach(s=>{const o=document.createElement('option');o.value=s;o.textContent=s;issueSel.appendChild(o);});
  }
  if(insSel&&insSel.children.length<=1){
    FILTER_OPTIONS.insurance.forEach(s=>{const o=document.createElement('option');o.value=s;o.textContent=s;insSel.appendChild(o);});
  }
  if(ageSel&&ageSel.children.length<=1){
    FILTER_OPTIONS.ages.forEach(a=>{const o=document.createElement('option');o.value=a;o.textContent=a;ageSel.appendChild(o);});
  }
  if(langSel&&langSel.children.length<=1){
    FILTER_OPTIONS.langs.forEach(l=>{const o=document.createElement('option');o.value=l;o.textContent=l;langSel.appendChild(o);});
  }
  applyFilters();
}
function applySearch(){
  dirPage=1;applyFilters();
}
function applyFilters(){
  const q=(document.getElementById('dir-query')?.value||'').toLowerCase();
  const city=(document.getElementById('dir-city')?.value||'').toLowerCase();
  const province=document.getElementById('f-province')?.value||'';
  const specialty=document.getElementById('f-specialty')?.value||'';
  const issue=document.getElementById('f-issue')?.value||'';
  const insurance=document.getElementById('f-insurance')?.value||'';
  const gender=document.getElementById('f-gender')?.value||'';
  const cost=+(document.getElementById('f-cost')?.value||0);
  const age=document.getElementById('f-age')?.value||'';
  const lang=document.getElementById('f-lang')?.value||'';
  const telehealth=document.getElementById('f-telehealth')?.checked||false;
  const inperson=document.getElementById('f-inperson')?.checked||false;
  const sliding=document.getElementById('f-sliding')?.checked||false;
  const accepting=document.getElementById('f-accepting')?.checked||false;

  filteredTherapists=THERAPISTS.filter(t=>{
    if(q&&!t.name.toLowerCase().includes(q)&&!t.bio.toLowerCase().includes(q)&&!t.specialties.some(s=>s.toLowerCase().includes(q))&&!t.issues.some(i=>i.toLowerCase().includes(q)))return false;
    if(city&&!t.city.toLowerCase().includes(city)&&!t.province.toLowerCase().includes(city))return false;
    if(province&&t.province!==province)return false;
    if(specialty&&!t.specialties.includes(specialty))return false;
    if(issue&&!t.issues.includes(issue))return false;
    if(insurance&&!t.insurance.includes(insurance))return false;
    if(gender&&t.gender!==gender)return false;
    if(cost&&t.fee.min>cost)return false;
    if(age&&!t.ages.includes(age))return false;
    if(lang&&!t.langs.includes(lang))return false;
    if(telehealth&&!t.telehealth)return false;
    if(inperson&&!t.inperson)return false;
    if(sliding&&!t.sliding)return false;
    if(accepting&&!t.accepting)return false;
    return true;
  });

  renderCards();
  renderActiveChips();
  updateClearBtn();
}
function renderCards(){
  const grid=document.getElementById('cards-grid');
  const empty=document.getElementById('empty-state');
  const count=document.getElementById('results-count');
  const pagination=document.getElementById('pagination');
  if(!grid)return;

  const total=filteredTherapists.length;
  const totalPages=Math.ceil(total/PER_PAGE);
  if(dirPage>totalPages)dirPage=1;
  const start=(dirPage-1)*PER_PAGE;
  const page=filteredTherapists.slice(start,start+PER_PAGE);

  if(count)count.innerHTML=`<strong>${total}</strong> therapist${total!==1?'s':''} found`;
  if(empty)empty.style.display=total===0?'block':'none';
  grid.style.display=total===0?'none':'grid';

  grid.innerHTML=page.map(t=>`
    <div class="t-card" onclick="showPage('profile',{id:${t.id}})">
      <div class="t-card-head">
        <div class="t-avatar">
          <img class="t-avatar-photo" src="${t.photo}" alt="${t.name}" onerror="this.style.display='none';this.nextElementSibling.style.display='flex'"/>
          <div class="t-avatar-initials" style="background:${t.color};display:none">${t.name.split(' ').map(w=>w[0]).slice(0,2).join('')}</div>
          <div class="t-verified"><svg width="10" height="10" viewBox="0 0 24 24" fill="white"><polyline points="20 6 9 17 4 12"/></svg></div>
        </div>
        <div class="t-info">
          <div class="t-name">${t.name}</div>
          <div class="t-cred">${t.cred}</div>
          <div class="t-meta">
            <span class="t-rating"><span class="t-rating-star">★</span>${t.rating}</span>
            <span>(${t.reviews} reviews)</span>
            <span>·</span>
            <span>${t.city}, ${t.province}</span>
            <span class="t-avail ${t.avail}">${t.avail==='soon'?'Available soon':'Waitlist'}</span>
          </div>
        </div>
      </div>
      <p class="t-bio">${t.bio}</p>
      <div class="tags">${t.specialties.slice(0,3).map(s=>`<span class="tag">${s}</span>`).join('')}</div>
      <div class="t-footer">
        <div class="t-badges">
          ${t.telehealth?'<span class="t-telehealth">📱 Telehealth</span>':''}
          ${t.sliding?'<span class="t-sliding">💚 Sliding scale</span>':''}
          ${t.accepting?'<span class="t-accepting">✓ Accepting clients</span>':''}
        </div>
        <div class="t-fee">$${t.fee.min}–$${t.fee.max} CAD</div>
      </div>
    </div>`).join('');

  if(pagination){
    if(totalPages<=1){pagination.innerHTML='';return;}
    let html=`<button onclick="dirPage--;renderCards()" ${dirPage===1?'disabled':''}>‹</button>`;
    for(let i=1;i<=totalPages;i++){
      html+=`<button onclick="dirPage=${i};renderCards()" style="${i===dirPage?'background:var(--primary);color:#fff;border-color:var(--primary)':''}">${i}</button>`;
    }
    html+=`<button onclick="dirPage++;renderCards()" ${dirPage===totalPages?'disabled':''}>›</button>`;
    pagination.innerHTML=html;
  }
}
function renderActiveChips(){
  const wrap=document.getElementById('active-chips');
  if(!wrap)return;
  const filters=[
    {id:'f-province',label:'Province'},{id:'f-specialty',label:'Specialty'},{id:'f-issue',label:'Issue'},
    {id:'f-insurance',label:'Insurance'},{id:'f-gender',label:'Gender'},{id:'f-cost',label:'Max cost'},
    {id:'f-age',label:'Age'},{id:'f-lang',label:'Language'},
    {id:'f-telehealth',label:'Telehealth',chk:true},{id:'f-inperson',label:'In-person',chk:true},
    {id:'f-sliding',label:'Sliding scale',chk:true},{id:'f-accepting',label:'Accepting clients',chk:true}
  ];
  wrap.innerHTML=filters.filter(f=>{
    const el=document.getElementById(f.id);
    return el&&(f.chk?el.checked:el.value);
  }).map(f=>{
    const el=document.getElementById(f.id);
    const val=f.chk?f.label:el.value;
    return `<span class="chip">${val}<button onclick="clearFilter('${f.id}')">×</button></span>`;
  }).join('');
}
function clearFilter(id){
  const el=document.getElementById(id);
  if(!el)return;
  if(el.type==='checkbox')el.checked=false;
  else el.value='';
  applyFilters();
}
function clearFilters(){
  ['f-province','f-specialty','f-issue','f-insurance','f-gender','f-cost','f-age','f-lang'].forEach(id=>{const el=document.getElementById(id);if(el)el.value='';});
  ['f-telehealth','f-inperson','f-sliding','f-accepting'].forEach(id=>{const el=document.getElementById(id);if(el)el.checked=false;});
  document.getElementById('dir-query')&&(document.getElementById('dir-query').value='');
  document.getElementById('dir-city')&&(document.getElementById('dir-city').value='');
  applyFilters();
}
function updateClearBtn(){
  const btn=document.getElementById('clear-btn');
  if(!btn)return;
  const hasFilter=
    ['f-province','f-specialty','f-issue','f-insurance','f-gender','f-cost','f-age','f-lang'].some(id=>{const el=document.getElementById(id);return el&&el.value;})||
    ['f-telehealth','f-inperson','f-sliding','f-accepting'].some(id=>{const el=document.getElementById(id);return el&&el.checked;});
  btn.style.display=hasFilter?'block':'none';
}
function toggleSidebar(){
  const sidebar=document.getElementById('sidebar');
  const overlay=document.getElementById('sidebar-overlay');
  const closeBtn=document.getElementById('sidebar-close-btn');
  if(sidebar)sidebar.classList.toggle('open');
  if(overlay)overlay.classList.toggle('open');
  if(closeBtn)closeBtn.style.display=sidebar&&sidebar.classList.contains('open')?'flex':'none';
}

