function buildAnalyticsChart(){
  const svg=document.getElementById('analytics-chart');
  const labelsEl=document.getElementById('chart-labels');
  if(!svg)return;
  const weeks=['Wk 1','Wk 2','Wk 3','Wk 4','Wk 5','Wk 6','Wk 7','Wk 8'];
  const vals=[72,88,65,110,95,130,145,187];
  const W=600,H=200,pad={t:10,r:20,b:30,l:40};
  const maxV=Math.max(...vals)*1.1;
  const xs=vals.map((_,i)=>pad.l+(i/(vals.length-1))*(W-pad.l-pad.r));
  const ys=vals.map(v=>pad.t+(1-v/maxV)*(H-pad.t-pad.b));
  const line=xs.map((x,i)=>`${i===0?'M':'L'}${x.toFixed(1)},${ys[i].toFixed(1)}`).join(' ');
  const area=`M${xs[0].toFixed(1)},${(H-pad.b).toFixed(1)} `+xs.map((x,i)=>`L${x.toFixed(1)},${ys[i].toFixed(1)}`).join(' ')+` L${xs[xs.length-1].toFixed(1)},${(H-pad.b).toFixed(1)} Z`;
  const isDk=document.documentElement.classList.contains('dark');
  svg.innerHTML=`
    <defs><linearGradient id="ag" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="${isDk?'#3da898':'#1e7b70'}" stop-opacity=".3"/><stop offset="100%" stop-color="${isDk?'#3da898':'#1e7b70'}" stop-opacity="0"/></linearGradient></defs>
    <path d="${area}" fill="url(#ag)"/>
    <path d="${line}" fill="none" stroke="${isDk?'#3da898':'#1e7b70'}" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>
    ${xs.map((x,i)=>`<circle cx="${x.toFixed(1)}" cy="${ys[i].toFixed(1)}" r="4" fill="${isDk?'#3da898':'#1e7b70'}"/><text x="${x.toFixed(1)}" y="${(ys[i]-10).toFixed(1)}" text-anchor="middle" font-size="10" fill="${isDk?'#7fa39e':'#4a5e5b'}">${vals[i]}</text>`).join('')}`;
  if(labelsEl)labelsEl.innerHTML=weeks.map(w=>`<span>${w}</span>`).join('');
}

// ── SIGNUP ────────────────────────────────────────────────────────────────
function buildSignupToggleGrids(){
  buildToggleGrid('spec-toggle-grid',FILTER_OPTIONS.specialties.slice(0,16));
  buildToggleGrid('issue-toggle-grid',FILTER_OPTIONS.issues.slice(0,16));
  buildToggleGrid('ins-toggle-grid',FILTER_OPTIONS.insurance);
  buildToggleGrid('lang-toggle-grid',FILTER_OPTIONS.langs);
  buildToggleGrid('approach-toggle-grid',["CBT","Mindfulness","EMDR","DBT","ACT","Psychodynamic","Gottman Method","Solution-Focused","Narrative Therapy","Somatic","IFS","Person-Centred"]);
  buildToggleGrid('age-toggle-grid',["Children (5–12)","Teens (13–17)","Young Adults (18–25)","Adults (26–64)","Seniors (65+)","Couples","Families"]);
}
function buildToggleGrid(id,items){
  const el=document.getElementById(id);
  if(!el||el.children.length>0)return;
  el.innerHTML=items.map(item=>`<button class="tag-toggle" onclick="this.classList.toggle('selected')">${item}</button>`).join('');
}
function signupNext(){
  if(signupStep<TOTAL_STEPS){
    updateStepDot(signupStep,'done');
    updateStepLine(signupStep,'done');
    signupStep++;
    updateStepDot(signupStep,'active');
    showSignupStep(signupStep);
  } else {
    // Complete
    updateStepDot(signupStep,'done');
    document.getElementById('signup-step-'+signupStep).style.display='none';
    document.getElementById('signup-complete').style.display='block';
    document.getElementById('signup-nav').style.display='none';
    launchConfetti();
  }
}
function signupBack(){
  if(signupStep>1){
    updateStepDot(signupStep,'pending');
    signupStep--;
    updateStepDot(signupStep,'active');
    updateStepLine(signupStep,'pending');
    showSignupStep(signupStep);
  }
}
function showSignupStep(n){
  for(let i=1;i<=TOTAL_STEPS;i++){
    const el=document.getElementById('signup-step-'+i);
    if(el)el.classList.toggle('active',i===n);
  }
  document.getElementById('signup-back').style.display=n>1?'inline-flex':'none';
  document.getElementById('signup-next').textContent=n===TOTAL_STEPS?'Complete signup →':'Continue →';
  if(n===2)buildSignupToggleGrids();
}
function updateStepDot(n,state){
  const dot=document.getElementById('dot-'+n);
  if(!dot)return;
  dot.className='step-dot'+{active:' active',done:' done',pending:''}[state];
  dot.textContent=state==='done'?'✓':n;
}
function updateStepLine(n,state){
  const line=document.getElementById('line-'+n);
  if(line)line.className='step-line'+(state==='done'?' done':'');
}
function selectPlan(plan){
  selectedPlan=plan;
  ['starter','professional','premium'].forEach(p=>{
    document.getElementById('plan-'+p)?.classList.toggle('selected',p===plan);
  });
}
function launchConfetti(){
  const colors=['#1e7b70','#8ca67e','#60b08a','#2dd4bf','#34d399','#6ee7b7'];
  for(let i=0;i<60;i++){
    const el=document.createElement('div');
    el.className='confetti-piece';
    el.style.cssText=`left:${Math.random()*100}vw;top:${Math.random()*-50}px;background:${colors[Math.floor(Math.random()*colors.length)]};border-radius:${Math.random()>0.5?'50%':'2px'};width:${6+Math.random()*8}px;height:${6+Math.random()*8}px;animation-delay:${Math.random()*2}s;animation-duration:${2+Math.random()*2}s`;
    document.body.appendChild(el);
    setTimeout(()=>el.remove(),4000);
  }
}

// ── BOOKING MODAL ─────────────────────────────────────────────────────────
let bkTherapist=null,bkStep=1,bkSession=null,bkDate=null,bkTime=null,bkCalMonth=null;

function openBooking(t){
  if(!t)return;
  bkTherapist=t;bkStep=1;bkSession=null;bkDate=null;bkTime=null;
  bkCalMonth=new Date();bkCalMonth.setDate(1);

  // Populate header
  const avEl=document.getElementById('bk-avatar');
  if(avEl)avEl.innerHTML=`<img src="${t.photo}" style="width:100%;height:100%;object-fit:cover"/>`;
  const nEl=document.getElementById('bk-name');if(nEl)nEl.textContent=t.name;
  const cEl=document.getElementById('bk-cred');if(cEl)cEl.textContent=t.cred;

  // Session types
  const sessions=[
    {id:'consult',label:'Free 15-min Consultation',sub:'Initial call to see if we’re a fit',price:'Free',duration:15},
    {id:'individual',label:'Individual Session (50 min)',sub:'Standard therapy session',price:`$${t.fee.min}–$${t.fee.max}`,duration:50},
    {id:'extended',label:'Extended Session (80 min)',sub:'Deeper work, EMDR, couples',price:`$${Math.round(t.fee.min*1.6)}–$${Math.round(t.fee.max*1.6)}`,duration:80}
  ];
  const stEl=document.getElementById('bk-session-types');
  if(stEl)stEl.innerHTML=sessions.map(s=>`
    <button class="bk-session-btn" data-sid="${s.id}" onclick="selectBkSession('${s.id}',this)">
      <div>
        <div style="font-size:13px;font-weight:600;color:var(--text)">${s.label}</div>
        <div style="font-size:11px;color:var(--text3);margin-top:2px">${s.sub}</div>
      </div>
      <span style="font-size:13px;font-weight:700;color:var(--primary);white-space:nowrap;margin-left:12px">${s.price}</span>
    </button>`).join('');

  // Reset steps
  document.querySelectorAll('.bk-step').forEach(s=>{s.classList.remove('active');});
  document.querySelectorAll('.bk-step-tab').forEach(t=>{t.classList.remove('active');});
  document.getElementById('bk-step-1').classList.add('active');
  document.querySelector('[data-bk-step="1"]').classList.add('active');
  updateBkNav();

  document.getElementById('booking-modal').style.display='block';
  document.body.style.overflow='hidden';
}

function closeBooking(){
  document.getElementById('booking-modal').style.display='none';
  document.body.style.overflow='';
}

function selectBkSession(id,btn){
  document.querySelectorAll('.bk-session-btn').forEach(b=>b.classList.remove('selected'));
  btn.classList.add('selected');
  bkSession=id;
}

function bkStepNext(){
  if(bkStep===1){
    if(!bkSession){alert('Please choose a session type.');return;}
    goBkStep(2);
  } else if(bkStep===2){
    if(!bkDate||!bkTime){alert('Please select a date and time.');return;}
    // Populate summary
    const labels={'consult':'Free 15-min Consultation','individual':'Individual Session (50 min)','extended':'Extended Session (80 min)'};
    const sumEl=document.getElementById('bk-summary');
    if(sumEl)sumEl.innerHTML=`<strong style="color:var(--text)">${bkTherapist.name}</strong><br>${labels[bkSession]}<br>📅 ${bkDate} at ${bkTime}<br>📍 ${bkTherapist.telehealth?'Telehealth (video call)':bkTherapist.city+', '+bkTherapist.province}`;
    goBkStep(3);
  }
}

function bkStepBack(){
  if(bkStep>1)goBkStep(bkStep-1);
}

function goBkStep(n){
  bkStep=n;
  document.querySelectorAll('.bk-step').forEach(s=>s.classList.remove('active'));
  document.querySelectorAll('.bk-step-tab').forEach(t=>t.classList.remove('active'));
  const stepEl=document.getElementById('bk-step-'+n);
  if(stepEl)stepEl.classList.add('active');
  const tabEl=document.querySelector('[data-bk-step="'+n+'"]');
  if(tabEl)tabEl.classList.add('active');
  if(n===2)renderBkCal();
  updateBkNav();
}

function updateBkNav(){
  const backBtn=document.getElementById('bk-back-btn');
  const nextBtn=document.getElementById('bk-next-btn');
  const footer=document.getElementById('bk-footer');
  if(backBtn)backBtn.style.visibility=bkStep>1?'visible':'hidden';
  if(nextBtn)nextBtn.style.display=bkStep<=2?'block':'none';
  if(footer)footer.style.display=bkStep===4?'none':'flex';
}

function renderBkCal(){
  const cal=document.getElementById('bk-cal');
  if(!cal)return;
  const now=new Date();
  const y=bkCalMonth.getFullYear(),m=bkCalMonth.getMonth();
  const days=['Su','Mo','Tu','We','Th','Fr','Sa'];
  const months=['January','February','March','April','May','June','July','August','September','October','November','December'];
  let html=`<div style="grid-column:1/-1;display:flex;align-items:center;justify-content:space-between;margin-bottom:8px">
    <button onclick="shiftBkCal(-1)" style="background:none;border:none;cursor:pointer;color:var(--text2);font-size:18px;padding:4px 8px">‹</button>
    <span style="font-size:13px;font-weight:700;color:var(--text)">${months[m]} ${y}</span>
    <button onclick="shiftBkCal(1)" style="background:none;border:none;cursor:pointer;color:var(--text2);font-size:18px;padding:4px 8px">›</button>
  </div>`;
  days.forEach(d=>{html+=`<div class="bk-cal-day header">${d}</div>`;});
  const firstDay=new Date(y,m,1).getDay();
  for(let i=0;i<firstDay;i++)html+=`<div class="bk-cal-day empty"></div>`;
  const daysInMonth=new Date(y,m+1,0).getDate();
  for(let d=1;d<=daysInMonth;d++){
    const dt=new Date(y,m,d);
    const isPast=dt<new Date(now.getFullYear(),now.getMonth(),now.getDate());
    const isSun=dt.getDay()===0;
    const dateStr=`${months[m]} ${d}, ${y}`;
    const isSelected=bkDate===dateStr;
    if(isPast||isSun){html+=`<div class="bk-cal-day past">${d}</div>`;}
    else{html+=`<div class="bk-cal-day avail${isSelected?' selected':''}" onclick="selectBkDate('${dateStr}',this)">${d}</div>`;}
  }
  cal.innerHTML=html;
  if(bkDate)renderBkTimes();
}

function shiftBkCal(dir){
  bkCalMonth.setMonth(bkCalMonth.getMonth()+dir);
  renderBkCal();
}

function selectBkDate(dateStr,el){
  document.querySelectorAll('.bk-cal-day').forEach(d=>d.classList.remove('selected'));
  el.classList.add('selected');
  bkDate=dateStr;bkTime=null;
  renderBkTimes();
}

function renderBkTimes(){
  const wrap=document.getElementById('bk-times');
  const label=document.getElementById('bk-time-label');
  if(!wrap)return;
  if(label)label.style.display='block';
  // Generate realistic time slots (skip some randomly based on date seed)
  const slots=['9:00 AM','9:30 AM','10:00 AM','10:30 AM','11:00 AM','12:00 PM','1:00 PM','1:30 PM','2:00 PM','3:00 PM','3:30 PM','4:00 PM','4:30 PM'];
  const seed=bkDate?bkDate.split('').reduce((a,c)=>a+c.charCodeAt(0),0):0;
  const avail=slots.filter((_,i)=>(seed+i*7)%4!==0);
  wrap.innerHTML=avail.map(s=>`<button class="bk-time-btn${bkTime===s?' selected':''}" onclick="selectBkTime('${s}',this)">${s}</button>`).join('');
}

function selectBkTime(t,btn){
  document.querySelectorAll('.bk-time-btn').forEach(b=>b.classList.remove('selected'));
  btn.classList.add('selected');
  bkTime=t;
}

function confirmBooking(){
  const fname=(document.getElementById('bk-fname')?.value||'').trim();
  const email=(document.getElementById('bk-email')?.value||'').trim();
  if(!fname||!email){alert('Please enter your name and email.');return;}
  // Show confirmed
  document.querySelectorAll('.bk-step').forEach(s=>s.classList.remove('active'));
  document.getElementById('bk-confirmed').classList.add('active');
  document.getElementById('bk-footer').style.display='none';
  const labels={'consult':'Free 15-min Consultation','individual':'Individual Session (50 min)','extended':'Extended Session (80 min)'};
  const detailEl=document.getElementById('bk-conf-detail');
  if(detailEl)detailEl.innerHTML=`<strong>${labels[bkSession]}</strong> with ${bkTherapist.name}<br>📅 ${bkDate} at ${bkTime}<br>A confirmation has been sent to <strong>${email}</strong>`;
}

// ── DASHBOARD HELPERS ─────────────────────────────────────────────────────
function handlePhotoUpload(input){
  const file=input.files[0];
  if(!file)return;
  if(file.size>5*1024*1024){alert('Image must be under 5MB.');return;}
  const reader=new FileReader();
  reader.onload=function(e){
    const preview=document.getElementById('dash-photo-preview');
    if(preview){preview.innerHTML='';preview.style.fontSize='0';
      const img=document.createElement('img');
      img.src=e.target.result;img.style.cssText='width:100%;height:100%;object-fit:cover';
      preview.appendChild(img);
    }
    const status=document.getElementById('dash-photo-status');
    if(status)status.style.display='block';
  };
  reader.readAsDataURL(file);
}

function saveBkLink(){
  const val=document.getElementById('booking-link-input')?.value||'';
  const saved=document.getElementById('bk-link-saved');
  if(saved)saved.style.display='block';
  // Store for use in booking modal (if set, open link instead)
  window._therapistBkLink=val;
}

function addBlockedDate(){
  const from=document.getElementById('block-from')?.value;
  const to=document.getElementById('block-to')?.value;
  if(!from)return;
  const list=document.getElementById('blocked-dates-list');
  if(!list)return;
  const fmtDate=s=>{const d=new Date(s+'T00:00:00');return d.toLocaleDateString('en-CA',{month:'short',day:'numeric'});};
  const label=to&&to!==from?`${fmtDate(from)} – ${fmtDate(to)}`:`${fmtDate(from)}`;
  const div=document.createElement('div');
  div.style.cssText='display:flex;align-items:center;justify-content:space-between;padding:10px 14px;background:var(--surface2);border-radius:var(--radius);border:1px solid var(--border)';
  div.innerHTML=`<div><div style="font-size:13px;font-weight:600;color:var(--text)">${label}</div><div style="font-size:11px;color:var(--text3)">Blocked</div></div><button onclick="this.closest('div').remove()" style="font-size:12px;color:var(--text3);background:none;border:none;cursor:pointer;padding:4px 8px">Remove</button>`;
  list.appendChild(div);
  if(document.getElementById('block-from'))document.getElementById('block-from').value='';
  if(document.getElementById('block-to'))document.getElementById('block-to').value='';
}

